Masks:=[0, 4, 275, 279, 3169, 3173, 3442, 3446, 12298, 12302, 12569, 12573, 15467, 15471, 15736, 15740];
p:=2; Qp:=pAdicField(2,400); Rp:=PolynomialRing(Qp); Fs:=[z[1]:z in Factorization(Rp!F)];
assert Sort([Degree(fi):fi in Fs]) eq [1,2,2];
H:=G cat [5/4-th,2-th,885-th];
LocG:=[* *]; LocB:=[* *];
for item in Decomposition(O,2) do
 I:=item[1]; L,mp:=Completion(K,I:Precision:=450); pi:=UniformizingElement(L); thL:=mp(th);
 fl:=[Polynomial(L,[L!c:c in Eltseq(fi)]):fi in Fs];
 scores:=[Valuation(Evaluate(fi,thL)):fi in fl];mx,idx:=Maximum(scores);assert mx gt 100; assert forall{ j : j in [1..#scores] | j eq idx or scores[j] lt 100 };
 A:=[];
 for z0 in H do
  z:=mp(z0);v:=Valuation(z);assert v mod 2 eq 0; z:=z/pi^v;Append(~A,z);
 end for;
 T:=[];
 for i in [1..#Fs] do
  z:=i eq idx select (-1)^(Degree(Fs[i])-1)*Evaluate(&*[fl[j]:j in [1..#Fs]|j ne i],thL) else (-1)^Degree(Fs[i])*Evaluate(fl[i],thL);
  v:=Valuation(z);assert v lt 100 and v mod 2 eq 0;z:=z/pi^v;Append(~T,z);
 end for;
 Append(~LocG,A[1..14]);Append(~LocB,T cat A[15..17]);
end for;
function bit(n,j) return (n div 2^(j-1)) mod 2; end function;
function prodmask(A,n) return &*[A[j]^bit(n,j):j in [1..#A]]; end function;
function sameclass(n,m,B)
 for i in [1..#B] do
  z:=prodmask(B[i],n)*prodmask(B[i],m);
  assert Valuation(z) eq 0 and AbsolutePrecision(z) gt 16;
  if not IsSquare(z) then return false;end if;
 end for;
 return true;
end function;
Reps:=[];
for n in [0..2^(#Fs+3)-1] do
 if not &or[sameclass(n,m,LocB):m in Reps] then Append(~Reps,n);end if;
end for;
print "LOCAL_CLASS_COUNT",#Reps;assert #Reps eq 16;
Surv:=[];
for n in Masks do
 ok:=false;
 for m in Reps do
  issq:=true;
  for i in [1..#LocG] do
   z:=prodmask(LocG[i],n)*prodmask(LocB[i],m);
   assert Valuation(z) eq 0 and AbsolutePrecision(z) gt 16;
   if not IsSquare(z) then issq:=false;break;end if;
  end for;
  if issq then ok:=true;break;end if;
 end for;
 if ok then Append(~Surv,n);end if;
end for;
print "SURVIVORS",Surv;
